import manifest from "../../../assets/textures/decorations/climber-foliage-atlas.json";
import type { ClimberFoliageTileId } from "./climber-foliage-atlas-layout";
import { createFoliageTileLookup, type FoliageAtlasManifest, type FoliageCardVertices,
  foliageCardVertices } from "./foliage-atlas-layout";

/** Generated by `npm run climber-foliage-atlas`; pure data, safe for workers and recipes. */
export const CLIMBER_FOLIAGE_ATLAS = manifest as unknown as FoliageAtlasManifest<ClimberFoliageTileId>;

export const getClimberFoliageTile = createFoliageTileLookup(CLIMBER_FOLIAGE_ATLAS);

/** The trimmed 8-vertex card of a climber tile (see `foliageCardVertices`). */
export const climberFoliageCardVertices = (id: ClimberFoliageTileId): FoliageCardVertices =>
  foliageCardVertices(getClimberFoliageTile(id));
